import { State, AssemblyType, Assemblies } from "./types";

// =========================================
// Inventory Related Types
// =========================================

/** @category Types */
export interface InventoryItem {
  id: string;
  item_id: string;
  location: { location_hash: string };
  quantity: number;
  tenant: string;
  type_id: number;
  name: string;
}

/** @category Types */
export interface EphemeralInventory {
  ownerId: string;
  ownerName: string;
  storageCapacity: bigint;
  usedCapacity: bigint;
  ephemeralInventoryItems: InventoryItem[];
}

// =========================================
// Module Types
// =========================================

/** @category Types */
export interface StorageModule {
  mainInventory: {
    capacity: string;
    usedCapacity: string;
    items: InventoryItem[];
  };
  ephemeralInventories: EphemeralInventory[];
  isParentNodeOnline: boolean;
}

/** @category Types */
export interface TurretModule {
  isParentNodeOnline: boolean;
}

/** @category Types */
export interface ManufacturingModule {
  isParentNodeOnline: boolean;
}

/** @category Types */
export interface RefineryModule {
  isParentNodeOnline: boolean;
}

/** @category Types */
export interface GateModule {
  linked: boolean;
  destinationId: string | undefined;
  inRange: AssemblyType<Assemblies.SmartGate>[];
  isParentNodeOnline: boolean;
}

/** @category Types */
export interface NetworkNodeModule {
  fuel: FuelResponse;
  energyProduction: number;
  energyMaxCapacity: number;
  totalReservedEnergy: number;
  linkedAssemblies: SmartAssemblyResponse[];
}

// =========================================
// Fuel Related Types
// =========================================

/** @category Types @internal */
export interface FuelResponse {
  quantity: number;
  burnRateInMs: number;
  burnStartTime: number;
  isBurning: boolean;
  lastUpdated: number;
  maxCapacity: number;
  previousCycleElapsedTime: number;
  unitVolume: number;
  typeId: number;
}

/** @category Types @internal */
export interface BurnResponse {
  isBurning: boolean;
  startTime: string;
}

// =========================================
// Location Related Types
// =========================================

/** @category Types @internal */
export interface SolarSystem {
  id: number;
  name: string;
  location: {
    x: number;
    y: number;
    z: number;
  };
}

// =========================================
// Character Related Types
// =========================================

/** @category Types @internal */
export interface SmartCharacterResponse {
  address: string;
  id: string;
  name: string;
  tribeId: number;
  characterId: number;
}

// =========================================
// Assembly Related Types
// =========================================

/** @category Types */
export interface SmartAssemblyResponse {
  id: string;
  item_id: number;
  type: Assemblies;
  typeDetails?: GameTypeResponse;
  name: string;
  state: State;
  character?: SmartCharacterResponse;
  solarSystem?: SolarSystem;
  energyUsage: number;
  typeId: number;
}

/** @category Types */
export interface DetailedAssemblyResponse extends SmartAssemblyResponse {
  location: {
    x: number;
    y: number;
    z: number;
  };
  description: string;
  dappURL: string;
}

/** @category Types */
export interface GameTypeResponse {
  categoryId: number;
  categoryName: string;
  description: string;
  groupId: number;
  groupName: string;
  iconUrl: string;
  id: number;
  mass: number;
  name: string;
  portionSize: number;
  radius: number;
  volume: number;
}
